import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the revert method of the Line class.
 */
public class Line_revert_TriageGen0Test {

    @Test
    public void testRevert() {
        // Setup: Create a line defined by two points
        Vector3D p1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D p2 = new Vector3D(4.0, 5.0, 6.0);
        Line originalLine = new Line(p1, p2);

        // Execute: Call the revert method
        Line revertedLine = originalLine.revert();

        // Verify: The returned line should be a new object (not the same instance)
        assertNotSame("revert() should return a new Line instance", originalLine, revertedLine);

        // Verify: The geometric properties should be identical (Line is undirected in essence, 
        // but revert in this context typically implies a copy or a specific transformation 
        // based on the implementation provided)
        assertEquals("Reverted line origin should be equal to original origin", 
            originalLine.getOrigin(), revertedLine.getOrigin(), 1e-10);

        assertEquals("Reverted line direction should be equal to original direction", 
            originalLine.getDirection(), revertedLine.getDirection(), 1e-10);

        // Verify: Check point mapping
        double abscissa = 5.0;
        Vector3D pointOnOriginal = originalLine.pointAt(abscissa);
        Vector3D pointOnReverted = revertedLine.pointAt(abscissa);
        assertEquals("Points at the same abscissa should be identical", 
            pointOnOriginal, pointOnReverted, 1e-10);

        // Verify: Similarity
        assertTrue("The reverted line should be similar to the original line", 
            originalLine.isSimilarTo(revertedLine));
    }

    @Test
    public void testRevertWithDifferentPoints() {
        // Setup: Create a line with different coordinate values
        Vector3D p1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D p2 = new Vector3D(1.0, 1.0, 1.0);
        Line originalLine = new Line(p1, p2);

        // Execute
        Line revertedLine = originalLine.revert();

        // Verify
        assertEquals("Origin must match", originalLine.getOrigin(), revertedLine.getOrigin(), 1e-10);
        assertEquals("Direction must match", originalLine.getDirection(), revertedLine.getDirection(), 1e-10);
        assertEquals("Distance to a point must match", originalLine.distance(new Vector3D(2, 2, 2)), 
            revertedLine.distance(new Vector3D(2, 2, 2)), 1e-10);
    }
}
